# =============================================================================
# Chapter 5 values: Multiple Regression
#
# Run from the project root:
#   Rscript r_code/figures/chapter_05_values.R
#
# Chapter 5 has no generated figures, so this script records only the model
# values behind Tables 5.1 through 5.6. The births models use births_2014.csv;
# the salary models use college_teacher_salary_2023.csv. figures/chapter_05/
# values.yml is generated by save_book_values(); do not edit it by hand.
# =============================================================================

source("r_code/figures/_book_figs.R")

suppressPackageStartupMessages({
  library(dplyr)
  library(readr)
})

# ---- Data -------------------------------------------------------------------

births <- read_csv("data/births_2014.csv", show_col_types = FALSE)
salary <- read_csv(
  "data/college_teacher_salary_2023.csv", show_col_types = FALSE
)

births <- births %>%
  mutate(
    smoker = as.integer(habit == "smoker"),
    mature_ind = as.integer(mature == "mature mom")
  )

# ---- Models -----------------------------------------------------------------

fit_5_1 <- lm(weight ~ visits, data = births)
fit_5_2 <- lm(weight ~ visits + weeks, data = births)
fit_5_4 <- lm(weight ~ weeks + habit, data = births)
fit_interaction <- lm(
  weight ~ weeks + smoker + mature_ind + smoker:mature_ind,
  data = births
)
fit_5_5 <- lm(Salary ~ Sex, data = salary)
fit_5_6 <- lm(Salary ~ Sex + Age + PhD, data = salary)

# ---- Helpers ----------------------------------------------------------------

coef_rows <- function(fit) {
  tab <- summary(fit)$coefficients
  data.frame(
    term = rownames(tab),
    estimate = tab[, "Estimate"],
    se = tab[, "Std. Error"],
    t = tab[, "t value"],
    p = tab[, "Pr(>|t|)"],
    check.names = FALSE, row.names = NULL
  )
}

model_record <- function(fit) {
  f <- summary(fit)$fstatistic
  list(
    n = nobs(fit),
    r_squared = summary(fit)$r.squared,
    adjusted_r_squared = summary(fit)$adj.r.squared,
    f = unname(f[1]),
    df1 = unname(f[2]),
    df2 = unname(f[3]),
    p = pf(f[1], f[2], f[3], lower.tail = FALSE),
    coefficients = coef_rows(fit)
  )
}

# ---- Values registry --------------------------------------------------------

values <- list(
  data = list(
    births_file = "births_2014.csv",
    births_rows = nrow(births),
    births_missing_visits = sum(is.na(births$visits)),
    births_missing_habit = sum(is.na(births$habit)),
    salary_file = "college_teacher_salary_2023.csv",
    salary_rows = nrow(salary)
  ),
  table_5_1 = c(
    list(model = "lm(weight ~ visits, data = births)"),
    model_record(fit_5_1)
  ),
  table_5_2 = c(
    list(model = "lm(weight ~ visits + weeks, data = births)"),
    model_record(fit_5_2)
  ),
  table_5_3 = list(
    note = paste(
      "Table 5.3 reports the two predictor coefficients from the Table 5.2",
      "model. The intercept is included here for completeness."
    ),
    coefficients = coef_rows(fit_5_2)
  ),
  table_5_4 = c(
    list(model = "lm(weight ~ weeks + habit, data = births)"),
    model_record(fit_5_4),
    list(
      note = paste(
        "The habit coefficient is the smoker-versus-nonsmoker difference;",
        "nonsmoker is the reference level."
      )
    )
  ),
  interaction_model = c(
    list(
      model = paste(
        "lm(weight ~ weeks + smoker + mature_ind + smoker:mature_ind,",
        "data = births)"
      ),
      note = paste(
        "smoker = 1 for smokers, 0 for nonsmokers; mature_ind = 1 for mature",
        "moms, 0 for younger moms."
      )
    ),
    model_record(fit_interaction)
  ),
  table_5_5 = c(
    list(model = "lm(Salary ~ Sex, data = salary)"),
    model_record(fit_5_5)
  ),
  table_5_6 = c(
    list(model = "lm(Salary ~ Sex + Age + PhD, data = salary)"),
    model_record(fit_5_6)
  ),
  table_5_7 = list(
    note = paste(
      "Simulated side-by-side comparison of three salary models. The table is",
      "illustrative; no dataset produces those coefficients."
    )
  ),
  table_5_8 = list(
    note = "Notation table; no calculated values."
  )
)

save_book_values(
  chapter = 5,
  values = values,
  conventions = list(
    note = paste(
      "Ordinary least squares. The births models treat habit as a smoker",
      "indicator with nonsmoker as the reference, and mature as a mature-mom",
      "indicator with younger mom as the reference. In the salary models, Sex",
      "is 1 = male and 0 = female, and PhD is 1 = holds a PhD and 0 = does not.",
      "No Type III sums of squares or contrast choices apply to these models."
    )
  ),
  source = "r_code/figures/chapter_05_values.R"
)
